<?php require_role('admin');$pageTitle='Supervisor Assignments';$pageSubtitle='Link each student to an academic supervisor and project';$students=db_all("SELECT u.* FROM users u WHERE u.role='student' AND u.status='active' ORDER BY u.full_name");$supervisors=db_all("SELECT * FROM users WHERE role='supervisor' AND status='active' ORDER BY full_name");$assigned=db_all("SELECT p.*,st.full_name student_name,st.matric_no,sp.full_name supervisor_name FROM projects p JOIN users st ON st.id=p.student_id LEFT JOIN users sp ON sp.id=p.supervisor_id ORDER BY st.full_name");include __DIR__.'/../includes/layout_top.php'; ?>
<div class="card"><div class="card-header"><div><h2>Create or update assignment</h2><p>A standard six-stage milestone plan is created automatically for a new project.</p></div></div><form method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="assign_supervisor"><div class="form-grid"><div class="form-group"><label>Student</label><select name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?= (int)$s['id'] ?>"><?= e($s['full_name'].' · '.$s['matric_no']) ?></option><?php endforeach;?></select></div><div class="form-group"><label>Supervisor</label><select name="supervisor_id" required><option value="">Select supervisor</option><?php foreach($supervisors as $s):?><option value="<?= (int)$s['id'] ?>"><?= e($s['full_name']) ?></option><?php endforeach;?></select></div><div class="form-group full"><label>Approved project title</label><input name="title" required></div><div class="form-group"><label>Expected completion date</label><input type="date" name="due_date"></div><div class="form-group" style="display:flex;align-items:end"><button class="button" type="submit">Save assignment</button></div></div></form></div>
<div class="card"><div class="card-header"><div><h2>Current assignments</h2><p>Supervisor allocation and active project records</p></div></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Supervisor</th><th>Project title</th><th>Stage</th><th>Due date</th><th>Progress</th></tr></thead><tbody><?php foreach($assigned as $a):$prog=progress_for_project((int)$a['id']);?><tr><td><strong><?= e($a['student_name']) ?></strong><br><?= e($a['matric_no']) ?></td><td><?= e($a['supervisor_name']?:'Unassigned') ?></td><td><?= e($a['title']) ?></td><td><?= e($a['current_stage']) ?></td><td><?= e(format_date($a['due_date'],'d M Y')) ?></td><td><span class="badge <?= $prog<40?'danger':($prog<75?'warning':'success') ?>"><?= $prog ?>%</span></td></tr><?php endforeach;?></tbody></table></div></div>
